        floor(h);var source=bone(h,"OwnBolt",4,2,10);var target=enemy(h,"OwnBoltEnemy",12,1,10);boolean[] hit={false};double[] travel={0};Vec3[] start={null};
        var seq=ready(h,source,target).thenExecute(()->{require(h,cast(h,source,target),SkillResult.SUCCESS,"bone marks visible enemy before normal paid attack");watchShots(source);start[0]=source.position();source.setNoAi(false);source.setHoldPosition(true);attack(h,source,target);});
        for(int i=0;i<100;i++)seq.thenIdle(1).thenExecute(()->{for(Entity e:PROBE.seenProjectiles.get(source.getUUID()))travel[0]=Math.max(travel[0],e.position().distanceTo(start[0]));if(target.getHealth()<1000&&!hit[0]){hit[0]=true;source.setNoAi(true);}});
        seq.thenExecute(()->{h.assertTrue(hit[0]&&PROBE.seenProjectiles.get(source.getUUID()).stream().anyMatch(e->e instanceof BoneWingBolt)&&travel[0]>1,"native ranged goal produced actual travelling paid bolt");close(h,1000-target.getHealth(),11.2,"paid own primary bolt receives mark bonus once");h.assertTrue(!target.isOnFire()&&!target.isCurrentlyGlowing(),"no original native fire or global reveal added");pass("OWN_BONE_GOAL_PAID_BOLT");}).thenSucceed();
