    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=1000)
    public static void remainingPostArmorAbsorptionAndForgeDamageIsMarkedBeforeActualGelConsumption(GameTestHelper h){
        floor(h);var source=bone(h,"Order",4,2,10);var attacker=slime(h,"Order",8,1,10);var normal=enemy(h,"OrderEnemy",10,1,5);var marked=enemy(h,"OrderEnemy",10,1,10);var shielded=enemy(h,"OrderEnemy",10,1,15);var second=bone(h,"Order",4,2,15);var guard=slime(h,"OrderEnemy",13,1,15);
        ready(h,source,attacker,normal,marked,shielded,second,guard).thenExecute(()->{for(var t:List.of(normal,marked)){t.getAttribute(Attributes.ARMOR).setBaseValue(10);t.setAbsorptionAmount(5);}require(h,cast(h,source,marked),SkillResult.SUCCESS,"armor/absorption target marked");position(attacker,normal.position().add(-1.4,0,0));double remaining=primaryHit(h,attacker,normal);h.assertTrue(remaining>0&&remaining<10,"real native armor and absorption reduced ordinary hit");position(attacker,marked.position().add(-1.4,0,0));ordinary(h,attacker,marked,remaining*1.12,"only actual remaining ordinary damage receives vulnerability");close(h,normal.getAbsorptionAmount(),0,"unmarked absorption consumed exactly its own five");close(h,marked.getAbsorptionAmount(),0,"mark does not enhance absorption depletion");require(h,cast(h,second,shielded),SkillResult.SUCCESS,"separate marked shield fixture");require(h,SkillService.request(player(h,guard.getOwnerName()),new SkillRequest(UnitSkill.GEL_GUARD,guard.getId(),guard.getUUID(),guard.rts().skills().revision(),shielded.getId(),shielded.getUUID())),SkillResult.SUCCESS,"real enemy Gel shield");watch(shielded,hit->hit.event.setAmount(7));position(attacker,shielded.position().add(-1.4,0,0));primaryHit(h,attacker,shielded);close(h,shielded.getHealth(),1000,"real Gel absorbs all marked final event amount");close(h,SkillEffects.shieldRemaining(shielded),12-7*1.12,"exact Forge final seven multiplied before Gel debit");pass("POST_ABSORPTION_FINAL_AMOUNT_MARK_THEN_GEL");}).thenSucceed();
    }

    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=1150)
    public static void expiredRevokedOrNewDuringCallbackMarksNeverRewriteLegalBaseDamage(GameTestHelper h){
        floor(h);var source=bone(h,"Timing",4,2,8);var fresh=bone(h,"Timing",4,2,13);var attacker=slime(h,"Timing",8,1,10);var target=enemy(h,"TimingEnemy",10,1,10);SkillResult[] late={null};
        ready(h,source,fresh,attacker,target).thenExecute(()->{require(h,cast(h,source,target),SkillResult.SUCCESS,"mark captured before actual primary hit");watch(target,hit->{String old=source.getOwnerName();source.setOwnerName(account("TimingForeign"));source.setOwnerName(old);});ordinary(h,attacker,target,10,"mark source ABA in final event removes only bonus, not legal ordinary base damage");h.assertTrue(mark(target,source.getOwnerName())==0,"actual revoked mark removed");watch(target,hit->late[0]=cast(h,fresh,target));ordinary(h,attacker,target,10,"new mark created during callback cannot retroactively affect entering hit");require(h,late[0],SkillResult.SUCCESS,"callback really created new mark");ordinary(h,attacker,target,11.2,"subsequent real primary hit captures fresh mark normally");watch(target,hit->hit.event.setAmount(0));ordinary(h,attacker,target,0,"zero final event amount cannot mint vulnerability damage");})
          .thenIdle(121).thenExecute(()->{h.assertTrue(mark(target,fresh.getOwnerName())==0&&cd(fresh)>0,"six-second effect expires without cooldown refund");ordinary(h,attacker,target,10,"ordinary base damage returns after expiration");pass("CAPTURE_ORIGINAL_MARK_CALLBACK_REVOCATION_EXPIRY");}).thenSucceed();
    }

    @GameTest(template="unit_isolation_arena",batch=FOG_BATCH,timeoutTicks=1200)
    public static void actualFogRasterLossClearsMarkAndReacquiringSightDoesNotRestoreIt(GameTestHelper h){
        floor(h);var source=bone(h,"FogOwner",4,2,10);var fresh=bone(h,"FogOwner",4,2,14);var attacker=slime(h,"FogOwner",8,1,10);var target=enemy(h,"FogEnemy",10,1,10);var spotter=DreamseekersMod.PINK_CHICKEN_SCOUT.get().create(h.getLevel());owned(h,spotter,"FogOwner",9,1,10);for(var e:List.of(source,fresh,attacker))e.getAttribute(AttributeRegistrar.SIGHT_RANGE.get()).setBaseValue(4);spotter.getAttribute(AttributeRegistrar.SIGHT_RANGE.get()).setBaseValue(4);PinkChickenScout[] replacement={null};long[] hiddenAt={0},castAt={0};
        ready(h,source,fresh,attacker,target,spotter).thenExecute(()->{fog=new FogFixture(h,source.getOwnerName());fog.install();h.assertTrue(fog.owner.distanceTo(target)>80,"player personal position is remote, not a hidden self-vision provider");})
          .thenWaitUntil(()->h.assertTrue(com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.isFogActiveFor(fog.owner)&&visible(fog.owner,target),"wait ordinary ten-tick server raster to expose target through actual owned spotter"))
          .thenExecute(()->{h.assertTrue(h.getLevel().players().contains(fog.owner),"authoritative viewer is an actual level player");require(h,SkillService.request(fog.owner,request(source,target)),SkillResult.SUCCESS,"real server-visible target permits mark");castAt[0]=h.getLevel().getGameTime();ordinary(h,attacker,target,11.2,"real visible primary hit benefits");h.assertTrue(!target.isCurrentlyGlowing()&&!com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.isBlockVisibleFor(fog.owner,target.getBlockX()+80,target.getBlockZ()),"mark neither glows globally nor exposes unrelated map columns");BlockPos retreat=h.absolutePos(new BlockPos(3,1,20));position(attacker,new Vec3(retreat.getX()+.5,retreat.getY(),retreat.getZ()+.5));spotter.discard();})
          .thenWaitUntil(()->h.assertTrue(!visible(fog.owner,target),"actual normal raster observes spotter loss, without writing mask fixtures"))
          .thenExecute(()->{hiddenAt[0]=h.getLevel().getGameTime();h.assertTrue(hiddenAt[0]-castAt[0]<120,"actual sight loss observed before natural mark expiration");h.assertTrue(mark(target,source.getOwnerName())==0&&cd(source)>0,"first observed actual hidden state clears mark without refund");require(h,SkillService.request(fog.owner,request(fresh,target)),SkillResult.HIDDEN,"another ready caster cannot mark hidden target");h.assertTrue(cd(fresh)==0,"hidden request does not spend cooldown");replacement[0]=DreamseekersMod.PINK_CHICKEN_SCOUT.get().create(h.getLevel());owned(h,replacement[0],"FogOwner",9,1,10);replacement[0].getAttribute(AttributeRegistrar.SIGHT_RANGE.get()).setBaseValue(4);})
          .thenWaitUntil(()->h.assertTrue(replacement[0].tickCount>3&&visible(fog.owner,target),"new real spotter is published and natural raster reacquires target"))
          .thenExecute(()->{h.assertTrue(mark(target,source.getOwnerName())==0,"re-illumination never revives removed mark");ordinary(h,attacker,target,10,"old mark stays absent after visibility returns");require(h,SkillService.request(fog.owner,request(fresh,target)),SkillResult.SUCCESS,"a genuine fresh authenticated cast may mark again");ordinary(h,attacker,target,11.2,"fresh mark is distinct from replayed hidden effect");System.out.println("BONE_MARK_REAL_FOG_REACQUIRED hiddenAt="+hiddenAt[0]+" visibleAt="+h.getLevel().getGameTime());fog.close();fog=null;pass("ACTUAL_FOG_MASK_LOSS_CLEAR_NO_REPLAY");}).thenSucceed();
    }
    private static boolean visible(ServerPlayer viewer,LivingEntity target){return com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.isBlockVisibleFor(viewer,target.getBlockX(),target.getBlockZ());}
    /** Real public fog toggle and native ten-tick raster; reflection is restricted to local test-player membership. */
    private static final class FogFixture implements AutoCloseable {
        final GameTestHelper helper;final ServerLevel level;final FakePlayer owner;final boolean oldEnabled,oldForce;final double size,centerX,centerZ;boolean closed;
        FogFixture(GameTestHelper h,String name){helper=h;level=h.getLevel();oldEnabled=com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.isEnabled();oldForce=level.getGameRules().getBoolean(GameRuleRegistrar.FORCE_FOG);var border=level.getWorldBorder();size=border.getSize();centerX=border.getCenterX();centerZ=border.getCenterZ();owner=new FakePlayer(level,new GameProfile(UUID.nameUUIDFromBytes(name.getBytes(java.nio.charset.StandardCharsets.UTF_8)),name));owner.connection=new QuietHandler(owner);}
        void install(){BlockPos origin=helper.absolutePos(BlockPos.ZERO);level.getGameRules().getRule(GameRuleRegistrar.FORCE_FOG).set(false,level.getServer());level.getWorldBorder().setCenter(origin.getX()+12,origin.getZ()+12);level.getWorldBorder().setSize(1280);owner.moveTo(origin.getX()+120,200,origin.getZ()+120,0,0);owner.setNoGravity(true);level.addNewPlayer(owner);membership(true);PlayerServerEvents.players.add(owner);PlayerServerEvents.orthoviewPlayers.add(owner);PlayerServerEvents.rtsPlayers.removeIf(p->p.name.equals(owner.getGameProfile().getName()));PlayerServerEvents.rtsPlayers.add(RTSPlayer.getNewPlayer(owner.getGameProfile().getName(),DreamseekersMod.DREAMSEEKERS,owner.getId(),0,true,-1L,-1L));com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.invalidateRtsCache();com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.setEnabled(true);helper.assertTrue(com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.isEnabled(),"public real fog enable accepted on actual bounded RTS-map fixture");}
        @SuppressWarnings("unchecked") void membership(boolean present){try{var list=level.getServer().getPlayerList();var players=net.minecraft.server.players.PlayerList.class.getDeclaredField("players");var uuids=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");players.setAccessible(true);uuids.setAccessible(true);List<ServerPlayer> ps=(List<ServerPlayer>)players.get(list);Map<UUID,ServerPlayer> ids=(Map<UUID,ServerPlayer>)uuids.get(list);if(present){if(!ps.contains(owner))ps.add(owner);ids.put(owner.getUUID(),owner);}else{ps.remove(owner);ids.remove(owner.getUUID(),owner);}}catch(ReflectiveOperationException e){throw new RuntimeException("real local test-player membership",e);}}
        @Override public void close(){if(closed)return;closed=true;PlayerServerEvents.rtsPlayers.removeIf(p->p.name.equals(owner.getGameProfile().getName()));membership(false);PlayerServerEvents.players.remove(owner);PlayerServerEvents.orthoviewPlayers.remove(owner);owner.serverLevel().removePlayerImmediately(owner,Entity.RemovalReason.DISCARDED);com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.onPlayerDisconnect(owner.getUUID());com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.invalidateRtsCache();level.getGameRules().getRule(GameRuleRegistrar.FORCE_FOG).set(false,level.getServer());com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.setEnabled(oldEnabled);level.getWorldBorder().setCenter(centerX,centerZ);level.getWorldBorder().setSize(size);level.getGameRules().getRule(GameRuleRegistrar.FORCE_FOG).set(oldForce,level.getServer());}
    }
