    private static void paidFactory(GameTestHelper h,int kind){
        floor(h);String owner="PaidFactory"+kind;var marker=bone(h,owner,6,2,10);Mob normal=paidSource(h,owner,kind,4,2,5),marked=paidSource(h,owner,kind,4,2,15);var plainTarget=enemy(h,owner+"Enemy",10,1,5);var markTarget=enemy(h,owner+"Enemy",10,1,15);double[] travel={0,0};Vec3[] starts=new Vec3[2];
        var seq=ready(h,marker,normal,marked,plainTarget,markTarget).thenExecute(()->{require(h,cast(h,marker,markTarget),SkillResult.SUCCESS,"real mark for one matched paid-factory lane");watchShots(normal);watchShots(marked);starts[0]=normal.position();starts[1]=marked.position();((RangedAttackerUnit)normal).performUnitRangedAttack(plainTarget,1);((RangedAttackerUnit)marked).performUnitRangedAttack(markTarget,1);h.assertTrue(plainTarget.getHealth()==1000&&markTarget.getHealth()==1000,"factory release never instant-hurts the distant enemy");});
        for(int i=0;i<40;i++)seq.thenIdle(1).thenExecute(()->{for(int j=0;j<2;j++){Mob source=j==0?normal:marked;for(Entity shot:PROBE.seenProjectiles.get(source.getUUID()))travel[j]=Math.max(travel[j],shot.position().distanceTo(starts[j]));}});
        seq.thenExecute(()->{for(int j=0;j<2;j++){Mob source=j==0?normal:marked;var shots=PROBE.seenProjectiles.get(source.getUUID());h.assertTrue(shots.size()==1&&travel[j]>1&&shots.get(0).isRemoved(),"actual registered single-use "+kind+" factory projectile flew then consumed: count="+shots.size()+" travel="+travel[j]);h.assertTrue(shots.get(0).getClass()==paidProjectileType(kind),"exact authorized paid projectile type, never an ordinary proxy");}close(h,1000-plainTarget.getHealth(),10,"unmarked paid ordinary primary retains original damage");close(h,1000-markTarget.getHealth(),11.2,"marked paid ordinary primary obtains exactly twelve percent");h.assertTrue(!plainTarget.isOnFire()&&!markTarget.isOnFire(),"no native fire/AOE fallback added");ledger(h,marker.getOwnerName());pass("PAID_FACTORY_TYPE_"+kind+"_REAL_FLIGHT_BASELINE_AND_MARK");}).thenSucceed();
    }

