    /** Each real trainable melee class executes its installed goal. Controlled NoAI goal invocation is not a natural cadence claim. */
    private static void paidMelee(GameTestHelper h,int kind){
        floor(h);String owner="PaidMelee"+kind;var marker=bone(h,owner,6,2,10);Mob normal=paidMeleeSource(h,owner,kind,4,1,5),marked=paidMeleeSource(h,owner,kind,4,1,15);var plainTarget=enemy(h,owner+"Enemy",10,1,5);var markTarget=enemy(h,owner+"Enemy",10,1,15);
        ready(h,marker,normal,marked,plainTarget,markTarget).thenExecute(()->{h.assertTrue(plainTarget.getHealth()==1000&&markTarget.getHealth()==1000,"no preparation or autonomous pre-hit");require(h,cast(h,marker,markTarget),SkillResult.SUCCESS,"actual mark precedes matched real trainable melee class");double plain=controlledMeleeHit(h,normal,plainTarget),enhanced=controlledMeleeHit(h,marked,markTarget);h.assertTrue(Double.isFinite(plain)&&plain>0,"actual installed ordinary goal must produce positive baseline for "+normal.getClass().getSimpleName());close(h,enhanced,plain*1.12,"same actual trainable melee class obtains one independent target vulnerability");h.assertTrue(mark(markTarget,marker.getOwnerName())>0,"positive class comparison used a live real mark");ledger(h,marker.getOwnerName());System.out.println("BONE_MARK_PAID_MELEE class="+normal.getClass().getSimpleName()+" goal="+((AttackerUnit)normal).getAttackGoal().getClass().getSimpleName()+" baseline="+plain+" marked="+enhanced+" controlledNoAI=true");pass("PAID_MELEE_TYPE_"+kind+"_INSTALLED_GOAL_BASELINE_AND_MARK");}).thenSucceed();
    }
    private static double controlledMeleeHit(GameTestHelper h,Mob source,LivingEntity target){
        var attacker=(AttackerUnit)source;var unit=(Unit)source;h.assertTrue(attacker.getAttackGoal() instanceof com.solegendary.reignofnether.unit.goals.AbstractMeleeAttackUnitGoal,"real class owns an installed ordinary melee goal");var goal=(com.solegendary.reignofnether.unit.goals.AbstractMeleeAttackUnitGoal)attacker.getAttackGoal();
        double gap=source.getBbWidth()/2.0+target.getBbWidth()/2.0+.1;position(source,target.position().add(-gap,0,0));source.setNoAi(true);attacker.setUnitAttackTargetForced(target);unit.setHoldPosition(true);h.assertTrue(source.getTarget()==target&&!source.getBoundingBox().intersects(target.getBoundingBox())&&source.hasLineOfSight(target),"published real enemy and non-overlapping visible melee stance");for(int i=0;i<(int)Math.ceil(attacker.getAttackCooldown())+2;i++)goal.tickAttackCooldown();target.invulnerableTime=0;float hp=target.getHealth();goal.start();goal.tick();
        if(goal instanceof com.solegendary.reignofnether.unit.goals.MeleeWindupAttackUnitGoal windup){int ticks=((KeyframeAnimated)source).getAttackWindupTicks();for(int i=0;i<ticks+2&&target.getHealth()==hp;i++)windup.checkAndPerformAttackWithWindup();}
        goal.stop();attacker.setUnitAttackTargetForced(null);return hp-target.getHealth();
    }
    private static Mob paidMeleeSource(GameTestHelper h,String owner,int kind,int x,int y,int z){Mob e=switch(kind){case 0->DreamseekersMod.FIREFLY_WORKER.get().create(h.getLevel());case 1->DreamseekersMod.BEETLE.get().create(h.getLevel());case 2->DreamseekersMod.BASALT_SNAIL.get().create(h.getLevel());case 3->DreamseekersMod.PINK_SLIME_UNIT.get().create(h.getLevel());case 4->DreamseekersMod.WIND_KNIGHT_UNIT.get().create(h.getLevel());case 5->DreamseekersMod.BEETLE_MOTHER_UNIT.get().create(h.getLevel());case 6->DreamseekersMod.SHADOW_GHOST_UNIT.get().create(h.getLevel());case 7->DreamseekersMod.TERRORBEAK_UNIT.get().create(h.getLevel());case 8->DreamseekersMod.CRAZY_TERRORBEAK_UNIT.get().create(h.getLevel());case 9->DreamseekersMod.SHADOW_GOLEM_UNIT.get().create(h.getLevel());default->throw new IllegalArgumentException("paid melee kind");};owned(h,e,owner,x,y,z);damage(e,10);if(e.getAttribute(AttributeRegistrar.AGGRO_RANGE.get())!=null)e.getAttribute(AttributeRegistrar.AGGRO_RANGE.get()).setBaseValue(0);return e;}

