    private static Mob nativeMelee(GameTestHelper h,String owner,int kind,int x,int y,int z){Mob e=switch(kind){case 0->EntityRegistrar.BEE_UNIT.get().create(h.getLevel());case 1->EntityRegistrar.KILLER_RABBIT_UNIT.get().create(h.getLevel());case 2->EntityRegistrar.IRON_GOLEM_UNIT.get().create(h.getLevel());case 3->EntityRegistrar.ROYAL_GUARD_UNIT.get().create(h.getLevel());case 4->EntityRegistrar.SLIME_UNIT.get().create(h.getLevel());default->throw new IllegalArgumentException("native melee kind");};owned(h,e,owner,x,y,z);if(e instanceof com.solegendary.reignofnether.unit.units.monsters.SlimeUnit slime)slime.setSize(2,true);damage(e,10);return e;}
    private static double controlledSlimePush(GameTestHelper h,Mob source,LivingEntity target){var slime=(com.solegendary.reignofnether.unit.units.monsters.SlimeUnit)source;h.assertTrue(!slime.onGround(),"actual spawned airborne NoAI slime uses native airborne push branch; no synthetic onGround flag");position(slime,target.position().add(-.8,0,0));slime.setUnitAttackTargetForced(target);slime.pushAttackCd=0;target.invulnerableTime=0;float hp=target.getHealth();slime.push(target);h.assertTrue(slime.pushAttackCd>0,"actual native push consumed its ordinary collision cooldown");slime.setUnitAttackTargetForced(null);return hp-target.getHealth();}

